/** @fileoverview Объявляет данные запуска Telegram Mini App для клиентской авторизации. */
interface Window {
  /** Объект, который добавляет скрипт Telegram после загрузки. */
  Telegram?: {
    /** Доступные при запуске мини-приложения данные и методы. */
    WebApp?: {
      /** Строка данных запуска для проверки подписи на сервере. */
      initData: string;
      /** Предварительно разобранные данные, ещё не проверенные сервером. */
      initDataUnsafe: {
        /** Пользователь, если Telegram передал его при запуске. */
        user?: {
          /** Числовой идентификатор пользователя Telegram. */
          id: number;
          /** Имя пользователя, указанное в Telegram. */
          first_name: string;
        };
      };
      /** Сообщает клиенту Telegram, что мини-приложение готово к показу. */
      ready?: () => void;
    };
  };
}
